  "yourBackup.title": "Dina designer, din säkerhetskopia",
  "yourBackup.body": "Dina designer bor i den här webbläsaren på din dator. Precis som med all data är bara det som finns en andra gång på en annan plats säkert. En trasig hårddisk, en ny dator, rensad webbläsardata eller en bugg – utan säkerhetskopia är arbetet borta. Att ta hand om den säkerhetskopian är upp till dig; inget program kan göra det åt dig. layerling gör det enkelt: ”{button}” samlar alla designer i en enda fil med ett klick. Spara den på ett USB-minne, i en molnmapp eller på en NAS efter varje större pass.",
