  "backups.folderHint": "Varje säkerhetskopia hamnar även där som en .lyl-fil döpt efter designen och tiden; gamla rensas där precis som i webbläsaren. En mapp som synkas till molnet eller ligger på en annan enhet är en andra plats.",
