  "customKeys.title": "Dina egna tangenter",
  "customKeys.intro": "Lägg valfritt kommando från kommandosökningen på en egen tangent: ett verktyg, en form, Centrera på arbetsytan, formpanelen. Dina tangenter sparas i den här webbläsaren.",
