  "interactiveHelp.nothing": "Inget att förklara här. Peka på en knapp, ett fält, ett handtag eller ett fönster.",
  "interactiveHelp.loading": "Slår upp i handboken ...",
  "interactiveHelp.noIndex": "Handboken är inte tillgänglig här ännu. Öppna den från översikten.",
  "interactiveHelp.panelOnly": "Den här delen har inget eget namn. Frågetecknet i fönstret öppnar det avsnitt i handboken som handlar om den.",
  "interactiveHelp.sectionOnly": "Handboken har ett avsnitt om den här delen.",
  "interactiveHelp.noMatch": "Handboken har inget om ”{name}” ännu. Prova att söka i den.",
  "interactiveHelp.also": "Även i handboken",
  "interactiveHelp.search": "Sök i handboken",
  "interactiveHelp.open": "Öppna i handboken",
  "interactiveHelp.started": "Interaktiv hjälp är på: klicka på en knapp, ett fält eller ett fönster för att läsa om det. Esc avslutar.",
  "interactiveHelp.ended": "Interaktiv hjälp är av",
  "shortcuts.interactiveHelp": "Slå på eller av interaktiv hjälp",
  "shortcuts.focusMode": "Fokusläge på eller av (döljer titelraden och sidfoten)",
  "installHint.chromium": "Installera med ikonen längst till höger i adressfältet, eller via webbläsarens meny under ”Installera som app”.",
  "installHint.safariMac": "I Safari: menyn Arkiv → ”Lägg till i Dock”.",
  "installHint.ios": "I Safari: Dela-ikonen → ”Lägg till på hemskärmen”.",
  "installHint.firefox": "Firefox kan inte installera appar – layerling startar ändå offline här i fliken.",
  "welcome.moreLanguagesTitle": "Ditt språk",
  "welcome.moreLanguagesBody": "programmet och handboken talar engelska, tyska och 18 andra språk; språklistan ligger längst upp till höger och i inställningarna på startsidan.",
  "welcome.moreOfflineTitle": "Fungerar offline",
  "welcome.moreOfflineBody": "efter första besöket startar layerling även utan internet – installera det som ett vanligt program, dina designer stannar på din dator.",
  "welcome.moreAiTitle": "Bygg med AI",
  "welcome.moreAiBody": "via MCP-gränssnittet kan en AI-assistent skapa och redigera former i en redigerare som den öppnar själv. Det kräver en kopia du kör själv (npm run dev eller Docker-avbilden); på layerling.com är AI-anslutningen avstängd.",
  "welcome.morePointsTitle": "Referenspunkter",
  "welcome.moreSearchTitle": "Kommandosökning",
  "welcome.moreSimplifyTitle": "Förenkla meshar",
  "welcome.moreSimplifyBody": "En importerad mesh med mycket stort antal trianglar reduceras till en bråkdel, med före-och-efter-vy och skjutreglage – så att snitt, gruppering och förflyttning förblir följsamma.",
  "welcome.moreHistoryTitle": "Historik",
  "welcome.moreLookTitle": "Utseende som du vill ha det",
  "welcome.moreLookBody": "Bakgrund och arbetsyta, axelpilar för X, Y och Z, kantlinjer på varje kropp, skissens färger samt kontrast, skuggor och ljusets riktning ställer du själv in i inställningarna – till exempel så att mörka kroppar inte flyter ihop med varandra. På långsammare datorer stänger snabbläget av allt krävande på en gång.",
  "welcome.moreControlsTitle": "Mus och 3D-mus",
  "welcome.moreControlsBody": "låter musknapparna fungera som i Bambu Studio och OrcaSlicer om du vill – vänsterdrag på tom yta vrider vyn, högerknappen flyttar den – och styr vyn med en SpaceMouse i Chrome och Edge.",
  "welcome.moreTabletTitle": "På surfplatta",
  "welcome.moreTabletBody": "ett finger arbetar med designen som vänster musknapp, två fingrar zoomar och flyttar vyn; ett Bluetooth-tangentbord ger kortkommandona.",
  "welcome.moreHistoryBody": "se tillbaka på valfritt tidigare läge i projektet med ett skjutreglage, utan att ändra något – exportera det läget, starta ett nytt projekt från det eller hämta tillbaka enskilda objekt ur det. Ångra och Gör om namnger steget de tar tillbaka med dess mått, och en lista namnger varje steg att hoppa till.",
  "welcome.moreDrawingTitle": "Ritning för verkstaden",
  "welcome.moreDrawingBody": "Exportera → Ritning: fram-, topp- och sidovy i skala 1:1 på ett ISO-ark, med yttermått, dolda kanter och en tabell över runda borrhål – som PDF eller SVG, att skriva ut eller ta med till svarven och fräsen. Toppvyn som SVG eller DXF går till laserskäraren, med schablonbryggor som håller kvar mitten i ett o eller ett b om du vill.",
  "welcome.moreSearchBody": "Tryck på Ctrl+K och skriv namnet på ett verktyg, en form eller ett kommando för att hoppa direkt dit – på engelska eller tyska, med kortkommandona visade bredvid varje träff. Kropparna i din design hittas också på namn. Valfria kommandon kan också läggas på egna tangenter, och knappar du aldrig använder kan tas bort från verktygsfältet i inställningarna – sökningen hittar dem ändå.",
  "welcome.moreHelpTitle": "Interaktiv hjälp",
  "welcome.moreHelpBody": "tryck på Skift+F1 eller frågetecknet och klicka sedan på valfri knapp, fält eller fönster: ett litet fönster visar den del av handboken som handlar om den.",
  "welcome.morePointsBody": "högerklicka på en kropp för att markera dess mittpunkt, hörn eller kantmittpunkter med punkter som inte skrivs ut och som former fäster mot – placera sedan ett hål exakt i mitten av en annan del.",
  "welcome.videosTitle": "Videor om layerling",
  "welcome.videosHint": "Gjorda av andra, inte av det här projektet. Länkarna öppnar YouTube i en ny flik; inget laddas därifrån förrän du klickar.",
  "welcome.help": "I redigeraren innehåller gruppen Hjälp en kort guide och listan över alla kortkommandona. I sidfoten sparar ”Felrapport” din design med allt som behövs för en rapport i forumet eller på GitHub.",
