  "lid.type.bothHint": "En platta som är en väggtjocklek bredare än kroppen med en läpp ner i öppningen och en kant utanpå: kroppens vägg sitter i ett spår däremellan, som på en matlåda.",
  "lid.type.flatHint": "Bara en platta lika stor som kroppen, att lägga ovanpå eller limma fast.",
  "lid.type.screwHint": "Ett lock med gänga på insidan av sin kant som skruvas på samma gänga på utsidan av kroppens topp, som på en burk. För en rund kropp: en cylinder, ett rör eller en rund kruka.",
  "lid.type.screwInHint": "En platta på kanten med en gängad tapp undertill som skruvas in i samma gänga på insidan av kroppens öppning. För en rund kropp med rund öppning: en cylinder, ett rör eller en rund kruka.",
  "lid.type.bayonetHint": "Ett lock som trycks ner över klackar på utsidan av kroppens topp och vrids för att låsas, som en bajonettfattning. För en rund kropp: en cylinder, ett rör eller en rund kruka.",
  "lid.type.slideHint": "En platta som skjuts in genom en vägg, med kanterna löpande i spår i de tre andra, som på ett pennskrin av trä. För en låda med raka väggar.",
