  "lid.threadStandardHint.pco1881": "De flesta vatten- och läskflaskor: 28 mm-halsen med den korta gängan.",
  "lid.threadStandardHint.pco1810": "Äldre dryckesflaskor: 28 mm-halsen med den högre gängan.",
  "lid.threadStandardHint.gl45": "Laboratorieflaskor med GL 45-gänga (DIN 168).",
  "lid.threadStandardHint.mason70": "Konservburkar (Mason jar) med vanlig öppning. Deras gänga har ingen offentlig ritning och måtten är uppmätta: prova först locket på din burk.",
  "lid.threadStandardHint.mason86": "Konservburkar (Mason jar) med vid öppning. Deras gänga har ingen offentlig ritning och måtten är uppmätta: prova först locket på din burk.",
  "lid.screwStandardHint": "Locket passar på en {standard}-hals: {major} mm över gängan, {pitch} mm per varv; det når {depth} mm ner. En kropp vars topp är lika bred som halsen under gängan ({from} till {to} mm) får halsens gänga; annars lämnas kroppen som den är och bara locket skapas. Flankerna följer standarden och är brantare än 45°.",
  "lid.neckMeasuring": "Mäter kroppens topp…",
  "lid.neckFits": "Kroppens topp: {measured} mm i diameter. En {standard}-hals är {from} till {to} mm under gängan, så din kropp får också gängan.",
  "lid.neckSize": "Kroppens topp: {measured} mm i diameter. En {standard}-hals kräver {from} till {to} mm under gängan, så bara locket skapas.",
  "lid.neckNotRound": "Kroppens topp är inte rund, så bara locket skapas.",
  "lid.neckFit": "Anpassa kroppen till halsen",
  "lid.neckFitHint": "Gör kroppen {diameter} mm i diameter och behåller dess höjd, så att Skapa lock ger den gängan.",
  "lid.neckFitting": "Anpassar kroppen…",
  "lid.neckFitByHand": "Gör toppen {diameter} mm bred, så får den också gängan.",
  "lid.bayonetLugs": "Klackar",
  "lid.bayonetTurn": "Vridning (0 = automatiskt)",
  "lid.bayonetTurnHint": "Upp till 90°, ett kvarts varv, vilket två klackar ger plats för. Fler klackar eller en liten kropp lämnar mindre plats för spåren och stoppen mellan dem: en vridning som inte får plats begränsas då till det som ryms, och statusraden meddelar det.",
  "lid.bayonetAxialGap": "Spelrum i höjdled",
  "lid.bayonetDetent": "Låsklackshöjd",
  "lid.bayonetDetentHint": "En liten ribba bakom varje låst klack som den klickar förbi, så att locket inte vrider sig tillbaka av sig självt; 0 för ingen, mindre om locket är för trögt att vrida.",
  "lid.bayonetHint": "{count} klackar på utsidan av kroppens topp, anpassade efter diametern, och ett L-format spår för varje på insidan av lockets kant. Tryck ner locket över dem och vrid {turn}° medurs tills det klickar. Klackar och spår lutar 45° undertill, så båda skrivs ut utan stöd.",
  "lid.bayonetLugsName": "{name} klackar",
  "lid.slideSide": "Skjuts in från",
  "lid.slideHint": "Lockets kanter löper i spår i tre väggar; den fjärde sänks ner till lockets undersida så att locket skjuts in över den och lockets ände fyller utskärningen. Spårens ovansidor lutar 45°, så lådan skrivs ut upprätt och locket upp och ner, båda utan stöd.",
  "lid.slideFrame": "Ram ovanför locket",
  "lid.slideFrameHint": "Hur långt under överkanten locket sitter, med väggarna stående runt det som en ram. 0: locket ligger i jämnhöjd med överkanten.",
  "lid.slideHintFrame": "Locket sitter under överkanten, med kanterna löpande i spår i tre väggar; det skjuts in genom en springa i den fjärde, som behåller sin fulla höjd ovanför, och lockets ände fyller springan. Lådan skrivs ut upprätt med springans ovansida överbryggad; locket skrivs ut upp och ner utan stöd.",
  "lid.slideBumpHint": "En liten knöl under lockets ände klickar förbi innerkanten av väggen det skjuts in genom, så att locket inte glider ut av sig självt. Knölhöjden anger hur långt den sticker ut under locket: mindre för en liten låda, mer för ett tydligare klick.",
  "lid.slideGroovesName": "{name} lockspår",
  "lid.tether": "Fästband",
  "lid.tetherHint": "Håller locket kvar vid kroppen när det är öppet, som på en dryckesflaska: två öppna ringar förbundna med ett band som skrivs ut plant bredvid locket, helst i PETG eller TPU (i PLA tål det bara några få böjningar). Den större ringen snäpper på locket underifrån, under en krage runt toppen, och den mindre på kroppen nedanför locket, där en vulst håller den. Båda snurrar fritt, så locket kan fortfarande skruvas på och av.",
  "lid.tetherName": "{name} fästband",
  "lid.tetherBeadName": "{name} fästbandsvulst",
  "lid.flipTop": "Flipplock",
  "lid.flipTopOpening": "Öppning",
  "lid.flipTopHint": "En rund öppning i lockets platta med en flik i jämnhöjd med ovansidan. En tunn remsa baktill på fliken fungerar som gångjärn, så locket sitter kvar och fliken lossnar aldrig. Lyft fliken med en nagel i spåret tvärs över den och tryck ner den tills den klickar. Skriv ut i PETG eller PP: i PLA bryts remsan efter några få böjningar.",
  "lid.topEdge": "Överkant",
  "lid.topEdge.square": "Rak",
