  "lid.topEdgeHint": "Avrundar eller fasar lockets yttre överkant. Locket skrivs ut upp och ner, så den här kanten ligger mot byggplattan: en fasning skrivs ut rent, och en avrundning på 1 eller 2 mm också.",
