  "shell.errorRoundedEdges": "Den här lådan har avrundade över- och underkanter, och väggen måste vara tydligt tunnare än den avrundningen. Välj en tunnare vägg, eller sätt avrundningen av över- och underkanterna till 0 innan du gröper ur den. Om det ändå misslyckas sparar ”Felrapport” i sidfoten designen för en rapport.",
  "shell.errorCannotHollow": "Den här kroppen kan inte gröpas ur, inte ens med en mycket tunn vägg. Dess kontur är troligen inte tillräckligt ren för CAD-kärnan; en utskärning som nuddar ytterkanten, till exempel en dörr skuren ända ner till underkanten på en importerad form, kan orsaka detta.",
