  "historyStep.offsetMany": "Förskjut {count} objekt",
  "guide.edges.offset": "Förskjut flyttar varje yta på en kropp med ett fast avstånd, utåt eller inåt. Förstora en kopia och behåll den som ett hål för att få spelrum för en presspassning, eller krymp en kropp för en tapp som ska passa i ett hål. Kroppar som bara är ett triangelnät går ofta inte att förskjuta.",
  "edge.revertSurfaceTexture": "Ytstruktur ({size} mm djup)",
  "deleteFace.title": "Ta bort yta",
  "deleteFace.subtitle": "Angränsande ytor sluter luckan",
  "deleteFace.help": "Klicka på ytorna som ska tas bort; ett klick till tar bort ytan ur urvalet igen. Ytorna runt omkring växer tills luckan är sluten: en avrundning, ett hål eller en tapp försvinner, och kroppen förblir exakt. Hårtunna ytor mellan ytor i samma plan följer med de valda ytorna.",
  "deleteFace.preparing": "Läser in ytorna…",
  "deleteFace.countNone": "Ingen yta vald ännu",
  "deleteFace.countOne": "1 yta vald",
  "deleteFace.countMany": "{count} ytor valda",
  "deleteFace.thinOne": "Togs med: 1 hårtunn yta",
  "deleteFace.thinMany": "Togs med: {count} hårtunna ytor",
  "deleteFace.apply": "Ta bort",
  "deleteFace.working": "Tar bort ytor…",
  "deleteFace.cancel": "Avbryt borttagning av ytor",
  "deleteFace.errorUnchanged": "De här ytorna kan inte tas bort: ytorna runt omkring sluter inte luckan. Markera varje yta av det som ska bort, till exempel alla ytor på en avrundning eller hela väggen i ett hål, och ingen yta av själva kroppen.",
  "deleteFace.errorMesh": "Den här kroppen har inga exakta ytor att ta bort: layerling lagrar den som ett nät, liksom importerade STL-, OBJ- eller 3MF-filer, delade, lindade eller förenklade kroppar, eller en mycket detaljerad form som en lång text. En del importerad som STEP har exakta ytor.",
  "deleteFace.errorResized": "Den här kroppen ändrades i storlek med ”Behåll kantstorlek vid skalning” påslagen, så dess exakta ytor stämmer inte längre överens med storleken. Ångra storleksändringen, ta bort ytorna och ändra storleken igen.",
  "deleteFace.errorProjectChanged": "Objektet eller projektet ändrades medan ytorna togs bort; försök igen.",
  "deleteFace.errorFailed": "Ytorna kunde inte tas bort. Välj andra ytor.",
  "deleteFace.errorNoFaces": "Ytorna på den här kroppen kunde inte läsas in. Stäng verktyget och öppna det igen.",
  "deleteFace.errorTooSlow": "Borttagningen av de här ytorna tog för lång tid och stoppades efter 45 sekunder; inget ändrades. CAD-kärnan klarar inte de här ytorna på den här delen: välj andra ytor, eller färre.",
