  "paint.wholeFaces": "Den här meshen är inte sluten: cirklar och lasson följer dess trianglar.",
  "status.honeycombConverted": "Bikaka konverterad till ett hålmönster: {count}",
  "welcome.moreHolePatternTitle": "Hålmönster",
  "welcome.moreHolePatternBody": "Klicka på en plan yta på en kropp och fördela hål över den: runda, kvadratiska, rektangulära, sexkantiga eller spår, i rutnät eller förskjutna, med avstånd, marginal till kanten och djup (genom hela kroppen eller ett angivet djup). En förhandsvisning visar hålen innan du skapar dem; de förblir vanliga hål, grupperade med kroppen – för ventilation, högtalargaller, korgar och kapslingar. Eller lägg en rad skruvhål längs kanten, ett hål i varje hörn, med planförsänkning eller konisk försänkning om du vill. En egen form kan upprepas på samma sätt, till exempel nitar eller durkplåt. På den runda väggen av en cylinder eller ett rör går hålen hela vägen runt, och varje hål pekar mot axeln.",
  "welcome.moreSupportRibTitle": "Stödribba",
  "welcome.moreSupportRibBody": "Skriv ut en del lutad på en kant utan slicerns stödstrukturer: klicka på den undre ytan så står en tunn ribba under den, på ett litet avstånd, på en oval fot, med pyttesmå bryggor som är exakt ett lager höga, håller delen och bryts av efteråt.",
  "welcome.moreStencilBridgesTitle": "Schablonbryggor",
  "welcome.moreStencilBridgesBody": "Skriv ut en schablon med genomskuren text: mitten i bokstäver som o, a och b får små bryggor till plattan, så breda och höga som du ställer in, så att inget faller ut.",
  "welcome.moreFaceTitle": "Tryck ut en yta",
  "welcome.moreFaceBody": "dra ut en plan yta på en kropp eller skär in en ficka i den, med indrag från kanten, rundade hörn och ett djup, visat som förhandsvisning – även på importerade STL-filer.",
  "welcome.moreTextureTitle": "Ytstruktur",
  "welcome.moreTextureBody": "lägg en relief på valfri kropp, för grepp eller utseende – lettring, spår, bikaka, tegelstenar, kolfiber, trädbark, träådring, rep, en bild som höjdkarta eller text, runt runda kroppar eller plant längs en axel. Upp till sex mönster ryms på en kropp, vart och ett på sina egna ytor. För en utskrift i två färger kan mönstret också bli en egen del i en egen färg.",
  "welcome.moreVaseTitle": "Vaser och krukor",
  "welcome.moreVaseBody": "en egen form för vaser, krukor och lampskärmar: kroppsform, tvärsnitt, vridning, mönster, dräneringshål, fat och lock – solid för slicerns vasläge eller ihålig. Ett tekannelock tar över vasens egen överkant så att mönstret löper vidare över skarven.",
  "welcome.moreOffsetTitle": "Förskjut och skär ut",
  "welcome.moreOffsetBody": "låt en exakt kropp växa eller krympa med ett angivet avstånd, runt om eller bara i sidled, för spelrummet i en presspassning, eller skär ut en del ur en annan med en spalt runt om, i ett enda steg.",
  "welcome.morePunchTitle": "Stansa",
  "welcome.morePunchBody": "skär konturen av en kropp rakt igenom en annan, var den än står framför den: silhuetten av en tekanna genom en skylt, en logotyp genom ett lock. Flytta eller vrid stansen och stansa igen; ett spelrum låter en utskriven del gå igenom.",
  "welcome.moreClearanceTitle": "Kontrollera spelrum",
  "welcome.moreClearanceBody": "innan du skriver ut delar som ska kunna röra sig – ett gångjärn som skrivs ut på plats, en flexi-leksak, ett lock i sin ask – hittar paren som överlappar, rör vid varandra eller kommer närmare än den spalt du anger.",
  "guide.select.holePattern": "Hålmönster (knappen i verktygsfältet bredvid Mönster, högerklick på en kropp eller Ctrl+K): klicka på en plan yta eller en rund vägg och ställ sedan in hålform, storlek, avstånd, placering, marginal och djup. Hålen visas som förhandsvisning; ”Skapa” lägger till dem som hål grupperade med kroppen. Dela upp grupp frigör dem igen.",
  "guide.select.faceTool": "Yta (knappen i verktygsfältet bredvid Hålmönster, högerklick på en kropp eller Ctrl+K): klicka på en plan yta, välj Utåt eller Inåt och ställ sedan in indrag från kanten, hörnradie och djup. Det som läggs till är en skisskropp grupperad med kroppen.",
  "guide.select.supportRib": "Stödribba (knappen i verktygsfältet, högerklick på en kropp eller Ctrl+K): klicka på den undre ytan av en del som skrivs ut lutad på en kant. En tunn ribba står under den på ett litet avstånd, på en oval fot, fäst mot delen med små bryggor som är ett lager höga; ställ in munstycket och lagren från din slicer.",
  "scalePercent.errorTooSmall": "”{name}” skulle bli mindre än 0,01 mm.",
