  "thread.axialClearanceHint": "Extra spel längs gängan, i mm, utöver spelrummet: varje varv på muttern blir så mycket tunnare medan diametern behålls. För en lättgående gänga som inte glappar i sidled: håll spelrummet runt 0,2 till 0,3 och ställ in 0,2 här. Vid 0 kommer spelet enbart från spelrummet, vilket öppnar flankerna ungefär hälften så mycket.",
  "thread.clearanceHint": "Extra utrymme över hela diametern. En utskriven gänga behöver mer än man tror: glipan mellan flankerna blir bara ungefär hälften så stor. Runt 0,3 går trögt, 0,4 är vanligt, 0,5 går lätt. Skriv ut ett provpar först.",
  "thread.boltClearanceHint": "Gör skruven så mycket tunnare, för en metallmutter som inte har något eget spel (0,3 till 0,4, lika mycket som en utskriven mutter skulle ha). Med en utskriven mutter lämnar du detta på 0 och ger muttern spelrummet.",
