  "screwBoss.screwOption": "{size} – pilothål {hole} mm",
  "screwBoss.insertHint": "Hålet är en millimeter djupare än insatsen. Utskrivna hål blir lite mindre än ritade: skriv ut ett skruvtorn på prov och justera hålet med en eller två tiondelar.",
  "screwBoss.screwHint": "Pilothål ungefär 0,8 gånger skruven, skruvtornet ungefär 2,5 gånger och hålet 2,5 skruvdiametrar djupt. Utskrivna hål blir lite mindre: testa ett först.",
  "screwBoss.customHint": "Skriv in det hål du behöver, till exempel 3,4 mm för en genomgående M3-skruv.",
  "screwBoss.through": "Lika djupt som skruvtornet: hålet går rakt igenom.",
  "screwBoss.wall": "Vägg runt hålet: {wall} mm.",
  "screwBoss.wallThin": "Väggen runt hålet är bara {wall} mm – det här fästelementet kräver minst {min} mm. Gör skruvtornet bredare.",
  "screwBoss.gussetsHint": "Tunna ribbor från skruvtornet ner till botten stagar upp det; 3 eller 4 är vanligt.",
  "screwBoss.gussetsNoRoom": "Det finns inte plats för så många: gör stödfenorna tunnare eller bredda fotytan.",
