  "snapFit.both": "Hake och fäste",
  "snapFit.hook": "Endast hake",
  "snapFit.catch": "Endast fäste",
  "snapFit.bothHint": "Båda står som när de är ihopsnäppta, med locket överst: placera hakens fot under locket och fästets baksida mot insidan av lådväggen, och använd sedan Separera delar för att dela dem.",
  "snapFit.hookHint": "Bara haken, för ett urtag i väggen eller ett eget fäste.",
  "snapFit.catchHint": "Bara klacken som haken snäpper under; dess baksida sitter mot väggen.",
  "snapFit.strainFine": "Böjs {strain} % vid roten när den snäpper i: lagom för PLA (upp till ca 2 %).",
  "snapFit.strainTough": "Böjs {strain} % vid roten: för mycket för PLA, men går bra för PETG eller ABS (upp till ca 4 %). En längre eller tunnare arm böjs mindre.",
  "snapFit.strainTooMuch": "Böjs {strain} % vid roten: den kommer att gå av. Gör armen längre eller tunnare, eller minska underskäringen.",
  "snapFit.leadHint": "Från det håll den trycks in: 30° glider in lätt, mindre vinkel går in mjukare.",
  "snapFit.retainHint": "90° håller permanent, 45° gör att den går att dra isär igen.",
  "snapFit.footHint": "Plattan som armen hänger i, sammanfogad med locket. 0: ingen fot.",
  "prop.ribStyle": "Typ",
