  "export.step.description": "CAD / B-Rep",
  "export.step.note": "Behåller rätblock, cylindrar, sfärer och koner som exakt CAD-geometri, liksom allt med avrundade eller fasade kanter och kroppar som kom in som STEP. Gängor, fjädrar och kugghjul följer också med som exakta kroppar. Avsmalnande, lutande och vridna former följer också med exakt. Text följer också med exakt, bokstav för bokstav med typsnittets egna kurvor. Importerade meshar följer med exaktgjorda, med sina plan, cylindrar, koner, sfärer och tori som verkliga ytor; en friformsmesh, som en figur, exporteras som STL.",
